/* MG_FIXTURE — minimal encounter core (mock build phase, contract v2). Pure logic only: the playable overlay is the LIVE Programmer's contract; this fixture proves the patch CONTRACT (anchors, M-assertions, parse checks, G-survival, the Director test hook, the Instructor's line) against the real build. */
const MG={armed:false,kind:null,done:false,spoken:false};
const MG_LINE='You are seen. Hold the flame steady, and the wary will kneel.';
if(typeof location!=='undefined'&&location.hash.indexOf('mg')>=0){MG.armed=true;MG.kind='first-contact';}
function mgBand(brightness,lo,hi){return brightness<lo?'drift':(brightness>hi?'break':'hold');}
function mgResolve(held,total){if(total<=0)return 'no_effect';return held>=Math.ceil(total*0.6)?'convert_devout':'no_effect';}
function mgArm(kind,st){st=st||MG;if(!st.armed&&!st.done){st.armed=true;st.kind=kind;return true;}return false;}
function mgFirstUseLine(sleep_no,st){st=st||MG;if(sleep_no!==0||st.spoken)return null;st.spoken=true;return MG_LINE;}

