out.push(['M3 mg fixture: first-use line speaks once, sleep 0 only', (function(){var st={spoken:false};var a=mgFirstUseLine(0,st);var b=mgFirstUseLine(0,st);var c=mgFirstUseLine(1,{spoken:false});return a===MG_LINE&&b===null&&c===null;})(), 'narration gate']);
